    "",
    "import sys, json\nimport itertools, functools, collections, math, bisect, string, heapq, random, operator\nfrom typing import *\nfrom collections import *\nfrom itertools import *\nfrom bisect import *\nfrom functools import *\nfrom math import *\nfrom string import *\nfrom operator import *\n\nclass Solution:\n    def lastInteger(self, n: int) -> int:\n        '''\n        \u6a21\u62df\n        \u4e00\u5f00\u59cb a0 = 1, d = 1, t = n, an = a0 + 1 * (t-1)\n        \u2460 a0 \u4e0d\u53d8 d *= 2 , t = (t+1) // 2\n        \u2461 \u53cd\u8fc7\u6765 d *= -1\n        '''\n        flag = True\n        # \u7b49\u5dee\u6570\u5217\n        # \u8d77\u70b9,\u5dee\u503c,\u6570\u76ee\n        a0,d,t = 1,1,n\n        # \u64cd\u4f5c\uff0cTrue \u4e3a\u64cd\u4f5c1\uff0cFalse \u4e3a\u64cd\u4f5c\u4e8c\n        flag = True\n        while t > 1:\n            if flag:\n                a0,d,t = a0,d * 2,(t+1) // 2\n            else:\n                # \u53cd\u8fc7\u6765\n                an = a0 + d * (t - 1)\n                # \u66f4\u65b0\u7b49\u5dee\u6570\u5217\n                a0,d,t = an,-d,t\n                # \u6a21\u62df\n                a0,d,t = a0,d * 2,(t+1) // 2\n                # \u518d\u53cd\u56de\u6765\n                an = a0 + d * (t - 1)\n                a0,d,t = an,-d,t\n            flag = not flag\n\n        return a0\n\ndef main():\n    _dec = json.JSONDecoder()\n    _text = sys.stdin.read()\n    _idx = 0\n    _args = []\n    while _idx < len(_text):\n        while _idx < len(_text) and _text[_idx] in ' \\t\\r\\n':\n            _idx += 1\n        if _idx >= len(_text):\n            break\n        try:\n            _obj, _end = _dec.raw_decode(_text, _idx)\n            _args.append(_obj)\n            _idx = _end\n        except Exception:\n            _nl = _text.find('\\n', _idx)\n            if _nl == -1:\n                _idx = len(_text)\n            else:\n                _idx = _nl + 1\n    _sol = Solution()\n\n    _ret = _sol.lastInteger(_args[0])\n    if _ret is None:\n        _out = ''\n    elif isinstance(_ret, (list, dict)):\n        _out = json.dumps(_ret, separators=(',', ':'))\n    elif isinstance(_ret, bool):\n        _out = 'true' if _ret else 'false'\n    elif isinstance(_ret, float):\n        _out = repr(_ret)\n    else:\n        _out = str(_ret)\n    sys.stdout.write(_out)\n\nmain()\n",
