    "",
    "import sys, json\nimport itertools, functools, collections, math, bisect, string, heapq, random, operator\nfrom typing import *\nfrom collections import *\nfrom itertools import *\nfrom bisect import *\nfrom functools import *\nfrom math import *\nfrom string import *\nfrom operator import *\n\nMOD = 10**9 + 7\nMX = 10**5\n\nfact = [0] * MX\ninv_fact = [0] * MX\n\n\ndef qpow(x, n):\n    res = 1\n    while n:\n        if n & 1:\n            res = res * x % MOD\n        x = x * x % MOD\n        n >>= 1\n    return res\n\n\ndef init():\n    if fact[0] != 0:\n        return\n    fact[0] = 1\n    for i in range(1, MX):\n        fact[i] = fact[i - 1] * i % MOD\n    inv_fact[MX - 1] = qpow(fact[MX - 1], MOD - 2)\n    for i in range(MX - 1, 0, -1):\n        inv_fact[i - 1] = inv_fact[i] * i % MOD\n\n\ndef comb(n, m):\n    return fact[n] * inv_fact[m] % MOD * inv_fact[n - m] % MOD\n\n\nclass Solution:\n    def countGoodArrays(self, n: int, m: int, k: int) -> int:\n        init()\n        return comb(n - 1, k) * m % MOD * qpow(m - 1, n - k - 1) % MOD\n\ndef main():\n    _dec = json.JSONDecoder()\n    _text = sys.stdin.read()\n    _idx = 0\n    _args = []\n    while _idx < len(_text):\n        while _idx < len(_text) and _text[_idx] in ' \\t\\r\\n':\n            _idx += 1\n        if _idx >= len(_text):\n            break\n        try:\n            _obj, _end = _dec.raw_decode(_text, _idx)\n            _args.append(_obj)\n            _idx = _end\n        except Exception:\n            _nl = _text.find('\\n', _idx)\n            if _nl == -1:\n                _idx = len(_text)\n            else:\n                _idx = _nl + 1\n    _sol = Solution()\n\n    _ret = _sol.countGoodArrays(_args[0], _args[1], _args[2])\n    if _ret is None:\n        _out = ''\n    elif isinstance(_ret, (list, dict)):\n        _out = json.dumps(_ret, separators=(',', ':'))\n    elif isinstance(_ret, bool):\n        _out = 'true' if _ret else 'false'\n    elif isinstance(_ret, float):\n        _out = repr(_ret)\n    else:\n        _out = str(_ret)\n    sys.stdout.write(_out)\n\nmain()\n",
