    "import sys, json\nimport itertools, functools, collections, math, bisect, string, heapq, random, operator\nfrom typing import *\nfrom collections import *\nfrom itertools import *\nfrom bisect import *\nfrom functools import *\nfrom math import *\nfrom string import *\nfrom operator import *\n\nclass Solution:\n    def maxBuilding(self, n: int, restrictions: List[List[int]]) -> int:\n        r = restrictions\n        # \u589e\u52a0\u9650\u5236 (1, 0)\n        r.append([1, 0])\n        r.sort()\n\n        # \u589e\u52a0\u9650\u5236 (n, n-1)\n        if r[-1][0] != n:\n            r.append([n, n - 1])\n\n        m = len(r)\n        \n        # \u4ece\u5de6\u5411\u53f3\u4f20\u9012\u9650\u5236\n        for i in range(1, m):\n            r[i][1] = min(r[i][1], r[i - 1][1] + (r[i][0] - r[i - 1][0]))\n        # \u4ece\u53f3\u5411\u5de6\u4f20\u9012\u9650\u5236\n        for i in range(m - 2, 0, -1):\n            r[i][1] = min(r[i][1], r[i + 1][1] + (r[i + 1][0] - r[i][0]))\n            \n        ans = 0\n        for i in range(m - 1):\n            # \u8ba1\u7b97 r[i][0] \u548c r[i][1] \u4e4b\u95f4\u7684\u5efa\u7b51\u7684\u6700\u5927\u9ad8\u5ea6\n            best = ((r[i + 1][0] - r[i][0]) + r[i][1] + r[i + 1][1]) // 2\n            ans = max(ans, best)\n        \n        return ans\n\ndef main():\n    _dec = json.JSONDecoder()\n    _text = sys.stdin.read()\n    _idx = 0\n    _args = []\n    while _idx < len(_text):\n        while _idx < len(_text) and _text[_idx] in ' \\t\\r\\n':\n            _idx += 1\n        if _idx >= len(_text):\n            break\n        try:\n            _obj, _end = _dec.raw_decode(_text, _idx)\n            _args.append(_obj)\n            _idx = _end\n        except Exception:\n            _nl = _text.find('\\n', _idx)\n            if _nl == -1:\n                _idx = len(_text)\n            else:\n                _idx = _nl + 1\n    _sol = Solution()\n\n    _ret = _sol.maxBuilding(_args[0], _args[1])\n    if _ret is None:\n        _out = ''\n    elif isinstance(_ret, (list, dict)):\n        _out = json.dumps(_ret, separators=(',', ':'))\n    elif isinstance(_ret, bool):\n        _out = 'true' if _ret else 'false'\n    elif isinstance(_ret, float):\n        _out = repr(_ret)\n    else:\n        _out = str(_ret)\n    sys.stdout.write(_out)\n\nmain()\n",
