    "\u6bcf\u884c\u4e00\u4e2a\u53c2\u6570\uff08JSON \u683c\u5f0f\uff09\uff0c\u4f9d\u6b21\u4e3a\uff1apoints\u3002",
    "\u8f93\u51fa integer \u7c7b\u578b\u7ed3\u679c\uff08JSON \u5e8f\u5217\u5316\uff09\u3002",
    "",
    "import sys, json\nimport itertools, functools, collections, math, bisect, string, heapq, random, operator\nfrom typing import *\nfrom collections import *\nfrom itertools import *\nfrom bisect import *\nfrom functools import *\nfrom math import *\nfrom string import *\nfrom operator import *\n\nclass Solution:\n    def countTrapezoids(self, points: List[List[int]]) -> int:\n        n = len(points)\n        inf = 10**9 + 7\n        slope_to_intercept = defaultdict(list)\n        mid_to_slope = defaultdict(list)\n        ans = 0\n        \n        for i in range(n):\n            x1, y1 = points[i]\n            for j in range(i + 1, n):\n                x2, y2 = points[j]\n                dx = x1 - x2\n                dy = y1 - y2\n                \n                if x2 == x1:\n                    k = inf\n                    b = x1\n                else:\n                    k = (y2 - y1) / (x2 - x1)\n                    b = (y1 * dx - x1 * dy) / dx\n                \n                mid = (x1 + x2) * 10000 + (y1 + y2)\n                slope_to_intercept[k].append(b)\n                mid_to_slope[mid].append(k)\n\n        for sti in slope_to_intercept.values():\n            if len(sti) == 1:\n                continue\n            \n            cnt = defaultdict(int)\n            for b_val in sti:\n                cnt[b_val] += 1\n            \n            total_sum = 0\n            for count in cnt.values():\n                ans += total_sum * count\n                total_sum += count\n\n        for mts in mid_to_slope.values():\n            if len(mts) == 1:\n                continue\n            \n            cnt = defaultdict(int)\n            for k_val in mts:\n                cnt[k_val] += 1\n            \n            total_sum = 0\n            for count in cnt.values():\n                ans -= total_sum * count\n                total_sum += count\n        \n        return ans\n\ndef main():\n    _dec = json.JSONDecoder()\n    _text = sys.stdin.read()\n    _idx = 0\n    _args = []\n    while _idx < len(_text):\n        while _idx < len(_text) and _text[_idx] in ' \\t\\r\\n':\n            _idx += 1\n        if _idx >= len(_text):\n            break\n        try:\n            _obj, _end = _dec.raw_decode(_text, _idx)\n            _args.append(_obj)\n            _idx = _end\n        except Exception:\n            _nl = _text.find('\\n', _idx)\n            if _nl == -1:\n                _idx = len(_text)\n            else:\n                _idx = _nl + 1\n    _sol = Solution()\n\n    _ret = _sol.countTrapezoids(_args[0])\n    if _ret is None:\n        _out = ''\n    elif isinstance(_ret, (list, dict)):\n        _out = json.dumps(_ret, separators=(',', ':'))\n    elif isinstance(_ret, bool):\n        _out = 'true' if _ret else 'false'\n    elif isinstance(_ret, float):\n        _out = repr(_ret)\n    else:\n        _out = str(_ret)\n    sys.stdout.write(_out)\n\nmain()\n",
