    "hard",
    "\u6570\u5b66",
    "\u4e00\u4e2a\u5e8f\u5217\u7684 \u5bbd\u5ea6 \u5b9a\u4e49\u4e3a\u8be5\u5e8f\u5217\u4e2d\u6700\u5927\u5143\u7d20\u548c\u6700\u5c0f\u5143\u7d20\u7684\u5dee\u503c\u3002\n\n\u7ed9\u4f60\u4e00\u4e2a\u6574\u6570\u6570\u7ec4 nums \uff0c\u8fd4\u56de nums \u7684\u6240\u6709\u975e\u7a7a \u5b50\u5e8f\u5217 \u7684 \u5bbd\u5ea6\u4e4b\u548c \u3002\u7531\u4e8e\u7b54\u6848\u53ef\u80fd\u975e\u5e38\u5927\uff0c\u8bf7\u8fd4\u56de\u5bf9 109 + 7 \u53d6\u4f59 \u540e\u7684\u7ed3\u679c\u3002\n\n\u5b50\u5e8f\u5217 \u5b9a\u4e49\u4e3a\u4ece\u4e00\u4e2a\u6570\u7ec4\u91cc\u5220\u9664\u4e00\u4e9b\uff08\u6216\u8005\u4e0d\u5220\u9664\uff09\u5143\u7d20\uff0c\u4f46\u4e0d\u6539\u53d8\u5269\u4e0b\u5143\u7d20\u7684\u987a\u5e8f\u5f97\u5230\u7684\u6570\u7ec4\u3002\u4f8b\u5982\uff0c[3,6,2,7] \u5c31\u662f\u6570\u7ec4 [0,3,1,6,2,2,7] \u7684\u4e00\u4e2a\u5b50\u5e8f\u5217\u3002\n\n\u00a0\n\n\u793a\u4f8b 1\uff1a\n\n```\n\u8f93\u5165\uff1anums = [2,1,3]\n\u8f93\u51fa\uff1a6\n\u89e3\u91ca\uff1a\u5b50\u5e8f\u5217\u4e3a [1], [2], [3], [2,1], [2,3], [1,3], [2,1,3] \u3002\n\u76f8\u5e94\u7684\u5bbd\u5ea6\u662f 0, 0, 0, 1, 1, 2, 2 \u3002\n\u5bbd\u5ea6\u4e4b\u548c\u662f 6 \u3002\n```\n\n\u793a\u4f8b 2\uff1a\n\n```\n\u8f93\u5165\uff1anums = [2]\n\u8f93\u51fa\uff1a0\n```\n\n\u00a0\n\n\u63d0\u793a\uff1a\n\n\t1 <= nums.length <= 105\n\n\t1 <= nums[i] <= 105",
    "\u6bcf\u884c\u4e00\u4e2a\u53c2\u6570\uff08JSON \u683c\u5f0f\uff09\uff0c\u4f9d\u6b21\u4e3a\uff1anums\u3002",
    "\u8f93\u51fa integer \u7c7b\u578b\u7ed3\u679c\uff08JSON \u5e8f\u5217\u5316\uff09\u3002",
    "",
    "import sys, json\nimport itertools, functools, collections, math, bisect, string, heapq, random, operator\nfrom typing import *\nfrom collections import *\nfrom itertools import *\nfrom bisect import *\nfrom functools import *\nfrom math import *\nfrom string import *\nfrom operator import *\n\nclass Solution:\n    def sumSubseqWidths(self, nums: List[int]) -> int:\n        nums.sort()\n        res = 0\n        MOD = 10 ** 9 + 7\n        x, y = nums[0], 2\n        for j in range(1, len(nums)):\n            res = (res + nums[j] * (y - 1) - x) % MOD\n            x = (x * 2 + nums[j]) % MOD\n            y = y * 2 % MOD\n        return (res + MOD) % MOD\n\ndef main():\n    _dec = json.JSONDecoder()\n    _text = sys.stdin.read()\n    _idx = 0\n    _args = []\n    while _idx < len(_text):\n        while _idx < len(_text) and _text[_idx] in ' \\t\\r\\n':\n            _idx += 1\n        if _idx >= len(_text):\n            break\n        try:\n            _obj, _end = _dec.raw_decode(_text, _idx)\n            _args.append(_obj)\n            _idx = _end\n        except Exception:\n            _nl = _text.find('\\n', _idx)\n            if _nl == -1:\n                _idx = len(_text)\n            else:\n                _idx = _nl + 1\n    _sol = Solution()\n\n    _ret = _sol.sumSubseqWidths(_args[0])\n    if _ret is None:\n        _out = ''\n    elif isinstance(_ret, (list, dict)):\n        _out = json.dumps(_ret, separators=(',', ':'))\n    elif isinstance(_ret, bool):\n        _out = 'true' if _ret else 'false'\n    elif isinstance(_ret, float):\n        _out = repr(_ret)\n    else:\n        _out = str(_ret)\n    sys.stdout.write(_out)\n\nmain()\n",
