    "",
    "import sys, json\nimport itertools, functools, collections, math, bisect, string, heapq, random, operator\nfrom typing import *\nfrom collections import *\nfrom itertools import *\nfrom bisect import *\nfrom functools import *\nfrom math import *\nfrom string import *\nfrom operator import *\n\nclass Solution:\n    def intersection(self, start1: List[int], end1: List[int], start2: List[int], end2: List[int]) -> List[float]:\n        # \u5224\u65ad (xk, yk) \u662f\u5426\u5728\u300c\u7ebf\u6bb5\u300d(x1, y1)~(x2, y2) \u4e0a\n        # \u8fd9\u91cc\u7684\u524d\u63d0\u662f (xk, yk) \u4e00\u5b9a\u5728\u300c\u76f4\u7ebf\u300d(x1, y1)~(x2, y2) \u4e0a\n        def inside(x1, y1, x2, y2, xk, yk):\n            # \u82e5\u4e0e x \u8f74\u5e73\u884c\uff0c\u53ea\u9700\u8981\u5224\u65ad x \u7684\u90e8\u5206\n            # \u82e5\u4e0e y \u8f74\u5e73\u884c\uff0c\u53ea\u9700\u8981\u5224\u65ad y \u7684\u90e8\u5206\n            # \u82e5\u4e3a\u666e\u901a\u7ebf\u6bb5\uff0c\u5219\u90fd\u8981\u5224\u65ad\n            return (x1 == x2 or min(x1, x2) <= xk <= max(x1, x2)) and (y1 == y2 or min(y1, y2) <= yk <= max(y1, y2))\n        \n        def update(ans, xk, yk):\n            # \u5c06\u4e00\u4e2a\u4ea4\u70b9\u4e0e\u5f53\u524d ans \u4e2d\u7684\u7ed3\u679c\u8fdb\u884c\u6bd4\u8f83\n            # \u82e5\u66f4\u4f18\u5219\u66ff\u6362\n            return [xk, yk] if not ans or [xk, yk] < ans else ans\n        \n        x1, y1 = start1\n        x2, y2 = end1\n        x3, y3 = start2\n        x4, y4 = end2\n\n        ans = list()\n        # \u5224\u65ad (x1, y1)~(x2, y2) \u548c (x3, y3)~(x4, y3) \u662f\u5426\u5e73\u884c\n        if (y4 - y3) * (x2 - x1) == (y2 - y1) * (x4 - x3):\n            # \u82e5\u5e73\u884c\uff0c\u5219\u5224\u65ad (x3, y3) \u662f\u5426\u5728\u300c\u76f4\u7ebf\u300d(x1, y1)~(x2, y2) \u4e0a\n            if (y2 - y1) * (x3 - x1) == (y3 - y1) * (x2 - x1):\n                # \u5224\u65ad (x3, y3) \u662f\u5426\u5728\u300c\u7ebf\u6bb5\u300d(x1, y1)~(x2, y2) \u4e0a\n                if inside(x1, y1, x2, y2, x3, y3):\n                    ans = update(ans, x3, y3)\n                # \u5224\u65ad (x4, y4) \u662f\u5426\u5728\u300c\u7ebf\u6bb5\u300d(x1, y1)~(x2, y2) \u4e0a\n                if inside(x1, y1, x2, y2, x4, y4):\n                    ans = update(ans, x4, y4)\n                # \u5224\u65ad (x1, y1) \u662f\u5426\u5728\u300c\u7ebf\u6bb5\u300d(x3, y3)~(x4, y4) \u4e0a\n                if inside(x3, y3, x4, y4, x1, y1):\n                    ans = update(ans, x1, y1)\n                # \u5224\u65ad (x2, y2) \u662f\u5426\u5728\u300c\u7ebf\u6bb5\u300d(x3, y3)~(x4, y4) \u4e0a\n                if inside(x3, y3, x4, y4, x2, y2):\n                    ans = update(ans, x2, y2)\n            # \u5728\u5e73\u884c\u65f6\uff0c\u5176\u4f59\u7684\u6240\u6709\u60c5\u51b5\u90fd\u4e0d\u4f1a\u6709\u4ea4\u70b9\n        else:\n            # \u8054\u7acb\u65b9\u7a0b\u5f97\u5230 t1 \u548c t2 \u7684\u503c\n            t1 = (x3 * (y4 - y3) + y1 * (x4 - x3) - y3 * (x4 - x3) - x1 * (y4 - y3)) / ((x2 - x1) * (y4 - y3) - (x4 - x3) * (y2 - y1))\n            t2 = (x1 * (y2 - y1) + y3 * (x2 - x1) - y1 * (x2 - x1) - x3 * (y2 - y1)) / ((x4 - x3) * (y2 - y1) - (x2 - x1) * (y4 - y3))\n            # \u5224\u65ad t1 \u548c t2 \u662f\u5426\u5747\u5728 [0, 1] \u4e4b\u95f4\n            if 0.0 <= t1 <= 1.0 and 0.0 <= t2 <= 1.0:\n                ans = [x1 + t1 * (x2 - x1), y1 + t1 * (y2 - y1)]\n\n        return ans\n\ndef main():\n    _dec = json.JSONDecoder()\n    _text = sys.stdin.read()\n    _idx = 0\n    _args = []\n    while _idx < len(_text):\n        while _idx < len(_text) and _text[_idx] in ' \\t\\r\\n':\n            _idx += 1\n        if _idx >= len(_text):\n            break\n        try:\n            _obj, _end = _dec.raw_decode(_text, _idx)\n            _args.append(_obj)\n            _idx = _end\n        except Exception:\n            _nl = _text.find('\\n', _idx)\n            if _nl == -1:\n                _idx = len(_text)\n            else:\n                _idx = _nl + 1\n    _sol = Solution()\n\n    _ret = _sol.intersection(_args[0], _args[1], _args[2], _args[3])\n    if _ret is None:\n        _out = ''\n    elif isinstance(_ret, (list, dict)):\n        _out = json.dumps(_ret, separators=(',', ':'))\n    elif isinstance(_ret, bool):\n        _out = 'true' if _ret else 'false'\n    elif isinstance(_ret, float):\n        _out = repr(_ret)\n    else:\n        _out = str(_ret)\n    sys.stdout.write(_out)\n\nmain()\n",
