    "",
    "import sys, json\nimport itertools, functools, collections, math, bisect, string, heapq, random, operator\nfrom typing import *\nfrom collections import *\nfrom itertools import *\nfrom bisect import *\nfrom functools import *\nfrom math import *\nfrom string import *\nfrom operator import *\n\nclass Solution:\n    def threeEqualParts(self, arr: List[int]) -> List[int]:\n        s = sum(arr)\n        if s % 3:\n            return [-1, -1]\n        if s == 0:\n            return [0, 2]\n\n        partial = s // 3\n        first = second = third = cur = 0\n        for i, x in enumerate(arr):\n            if x:\n                if cur == 0:\n                    first = i\n                elif cur == partial:\n                    second = i\n                elif cur == 2 * partial:\n                    third = i\n                cur += 1\n\n        n = len(arr)\n        length = n - third\n        if first + length <= second and second + length <= third:\n            i = 0\n            while third + i < n:\n                if arr[first + i] != arr[second + i] or arr[first + i] != arr[third + i]:\n                    return [-1, -1]\n                i += 1\n            return [first + length - 1, second + length]\n        return [-1, -1]\n\ndef main():\n    _dec = json.JSONDecoder()\n    _text = sys.stdin.read()\n    _idx = 0\n    _args = []\n    while _idx < len(_text):\n        while _idx < len(_text) and _text[_idx] in ' \\t\\r\\n':\n            _idx += 1\n        if _idx >= len(_text):\n            break\n        try:\n            _obj, _end = _dec.raw_decode(_text, _idx)\n            _args.append(_obj)\n            _idx = _end\n        except Exception:\n            _nl = _text.find('\\n', _idx)\n            if _nl == -1:\n                _idx = len(_text)\n            else:\n                _idx = _nl + 1\n    _sol = Solution()\n\n    _ret = _sol.threeEqualParts(_args[0])\n    if _ret is None:\n        _out = ''\n    elif isinstance(_ret, (list, dict)):\n        _out = json.dumps(_ret, separators=(',', ':'))\n    elif isinstance(_ret, bool):\n        _out = 'true' if _ret else 'false'\n    elif isinstance(_ret, float):\n        _out = repr(_ret)\n    else:\n        _out = str(_ret)\n    sys.stdout.write(_out)\n\nmain()\n",
